"""Operational data contracts, lineage manifest, run metadata and anomaly flags."""
from pathlib import Path
import json, hashlib, datetime
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; RAW=ROOT/'data/raw'; OUT=ROOT/'data/processed'; REPORTS=ROOT/'reports'; DOCS=ROOT/'docs'

def sha256(path):
 h=hashlib.sha256()
 with path.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
 return h.hexdigest()

def main():
 contracts={
  'payments':{'primary_key':['payment_id'],'required':['payment_id','account_id','event_at','payment_status','amount'],'types':{'amount':'numeric','event_at':'timestamp','payment_status':'enum: SUCCESS|FAILED|PENDING|REVERSED'},'freshness':'event_at watermark; late events trigger affected-month recompute','owner':'Payments/Finance','quality_rules':['payment_id non-null','amount parseable','account_id resolves to account master','same-timestamp conflicting updates quarantined pending tie-break rule']},
  'accounts':{'primary_key':['account_id'],'required':['account_id','borrower_id','principal_amount','outstanding_amount','status'],'owner':'Lending/Collections','quality_rules':['account_id unique in canonical snapshot','outstanding non-negative unless approved exception','dated eligibility snapshot required for recovery-rate denominator']},
  'calls':{'primary_key':['call_id'],'required':['call_id','account_id','event_at','agent_id','vendor_id'],'owner':'Telephony Operations','quality_rules':['call_id unique after source event resolution','vendor timezone contract defined','vendor/version disposition crosswalk approved']},
  'daily_targeting':{'primary_key':['target_id'],'required':['target_id','account_id','target_date','recommended_channel'],'owner':'Collections Strategy','quality_rules':['target_id unique','treatment assignment and exposure timestamp retained','randomized holdout required for causal lift']}}
 (DOCS/'data_contracts.json').write_text(json.dumps(contracts,indent=2),encoding='utf-8')
 outputs=[]
 for p in sorted(RAW.glob('*.csv')):
  d=pd.read_csv(p,low_memory=False); outputs.append({'path':str(p.relative_to(ROOT)),'sha256':sha256(p),'rows':len(d),'columns':list(d.columns)})
 for p in sorted(OUT.glob('*.csv')):
  try: rows=sum(1 for _ in p.open(encoding='utf-8'))-1
  except Exception: rows=None
  outputs.append({'path':str(p.relative_to(ROOT)),'sha256':sha256(p),'rows':rows})
 lineage={'generated_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'entrypoint':'python src/run_all.py','stages':[{'stage':'canonicalization_and_golden','script':'src/run_pipeline.py','inputs':'data/raw/*.csv','outputs':['data/processed/*_canonical.csv','data/processed/payments_canonical.csv','data/processed/monthly_recovery_metrics.csv','data/processed/golden_dataset_account_month.csv']},{'stage':'extended_descriptive_analysis','script':'src/extended_analysis.py','inputs':['data/processed/payments_canonical.csv','data/processed/golden_dataset_account_month.csv','data/raw/daily_targeting.csv'],'outputs':['data/processed/targeting_descriptive_association.csv','data/processed/campaign_descriptive_association.csv','data/processed/account_vintage_metrics.csv','data/processed/mix_adjusted_descriptive_metrics.csv']},{'stage':'forensic_audits','script':'src/forensic_analysis.py','inputs':'raw and canonical data','outputs':'data/processed/*audit*.csv and expanded forensic report'},{'stage':'operational_controls','script':'src/operational_controls.py','outputs':['docs/data_contracts.json','reports/lineage_manifest.json','data/processed/monthly_anomaly_flags.csv']}],'files':outputs}
 (REPORTS/'lineage_manifest.json').write_text(json.dumps(lineage,indent=2),encoding='utf-8')
 m=pd.read_csv(OUT/'monthly_recovery_metrics.csv'); m['recovered_amount']=pd.to_numeric(m.recovered_amount,errors='coerce'); m['rolling_median_3m']=m.recovered_amount.rolling(3,min_periods=2).median(); m['rolling_mad_3m']=(m.recovered_amount-m.rolling_median_3m).abs().rolling(3,min_periods=2).median(); m['robust_deviation']= (m.recovered_amount-m.rolling_median_3m)/(1.4826*m.rolling_mad_3m.replace(0,pd.NA)); m['anomaly_flag']=m.robust_deviation.abs().gt(3); m['partial_month']=m.partial_month.astype(bool); m['review_note']='Exploratory alert only; seasonality, partial month and mix can create false positives'; m.to_csv(OUT/'monthly_anomaly_flags.csv',index=False)
 doc='''# Production operating model (implementation contract)\n\n## Layering and ownership\n- **Raw/immutable:** retain source payload, ingestion timestamp, source file/object ID, source schema version and checksum. Never overwrite raw data.\n- **Staging:** parse types, normalize whitespace/status casing, preserve source values alongside normalized values, quarantine parse failures.\n- **Clean/canonical:** enforce approved keys, latest-event rules and crosswalks. For same-timestamp conflicts, quarantine until a source sequence/event ID is available; do not assume arbitrary ordering is authoritative.\n- **Golden:** one row per account × reporting month, with explicit snapshot/effective dates and lineage to source event IDs. A historical recovery-rate denominator requires dated month-opening eligible balances; the current snapshot is not a substitute.\n- **Metrics/features:** version metric definitions, cohort rules, attribution windows and exclusion policies. Keep amount trend distinct from recovery rate.\n- **Serving:** dashboard reads versioned metric outputs and displays observation cutoff, partial-month state, freshness, quality status and definition.\n\n## Incremental processing, late arrivals and backfills\n1. Persist a per-source watermark and run ID. Ingest by source update timestamp plus a configurable lookback window.\n2. Upsert idempotently using source primary key + source event/version; retain prior versions in raw history.\n3. When a late event arrives, recompute its affected payment reference, account, and all impacted reporting months; recompute derived account-month rows for affected accounts/months.\n4. Support `--from-date`/`--to-date` backfills in a warehouse implementation; record who requested it, reason, row counts and before/after metric deltas.\n5. Reconcile raw → canonical counts and amounts; fail the run on unexplained variance above a Finance-approved tolerance.\n\n## Monitoring and response\n- Freshness: latest event time vs expected SLA; alert on stale sources.\n- Volume: source rows and canonical rows vs rolling baseline; investigate sudden drops/spikes.\n- Quality: null keys, duplicate keys, orphan foreign keys, invalid statuses, negative/implausible amounts, unresolved conflicts, and canonicalization deltas.\n- Metrics: robust monthly amount anomaly flags in `data/processed/monthly_anomaly_flags.csv` are exploratory only; add seasonality and partial-month handling before paging.\n- Ownership: data engineering owns pipeline/lineage, Finance owns payment lifecycle and ledger reconciliation, Operations owns vendor-code crosswalk, HR/vendor management owns agent identity, Analytics owns metric definitions and experiments.\n\n## Current implementation boundary\nThis repository generates reproducible local CSV outputs, SHA-256 input/output lineage metadata, JSON data contracts and exploratory anomaly flags. It is **not** a deployed scheduler/warehouse: persistent watermarks, transactional upserts, alert delivery, approval workflow and a true historical balance snapshot require infrastructure and source contracts not included in the supplied synthetic files.\n'''
 (DOCS/'production_operating_model.md').write_text(doc,encoding='utf-8')
 print('Operational contracts, lineage manifest and anomaly flags built.')
if __name__=='__main__': main()
